SELECT * FROM favorite
WHERE user_id = #{userId}
ORDER BY create_time DESC

SELECT f.* FROM favorite f
INNER JOIN question q ON f.question_id = q.id
WHERE f.user_id = #{userId}
  AND q.is_deleted = 0

  AND q.subject_id = #{subjectId}



    AND q.quiz_type = #{quizType}





    AND (q.quiz_type IS NULL OR (q.quiz_type != 'code' AND q.quiz_type != 'interview'))


ORDER BY f.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM favorite f
INNER JOIN question q ON f.question_id = q.id
WHERE f.user_id = #{userId}
  AND q.is_deleted = 0

  AND q.subject_id = #{subjectId}



    AND q.quiz_type = #{quizType}





    AND (q.quiz_type IS NULL OR (q.quiz_type != 'code' AND q.quiz_type != 'interview'))
